function toast(text){const host=$('#modal').open?$('#modal'):document.body;if($('#toast').parentElement!==host)host.append($('#toast'));$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2900);}
function sound(kind='tap'){audio.configure(settings);if(kind!=='step')audio.unlock();audio.play(kind);}
function save(silent=true){try{Beta.sync(state);PC.sync(state);P.sync(state);CP.sync(state);state.savedAt=M.stamp(state);localStorage.setItem(M.SAVE_KEY,JSON.stringify(state));storageOK=true;hasSave=true;if(!silent)toast('이 기기에 현재 교실을 저장했습니다.');return true;}catch{storageOK=false;if(!silent)toast('저장 공간을 사용할 수 없습니다. 설정에서 저장 파일을 내려받아 주세요.');return false;}}
