function ambient(){
 if(M.movementBusy(state)||outingPending()||!scene||!running||$('#modal').open||document.hidden||state.ended)return;
 const fresh=People.data(state).socialFeed.find(f=>!state.ambientSeen[f.id]&&scene.actors.get(f.a)?.group.visible&&scene.actors.get(f.b)?.group.visible);if(fresh){state.ambientSeen[fresh.id]=true;scene.facePair?.(fresh.a,fresh.b);scene.speak(fresh.a,fresh.line,fresh.nameA);save();return;}
 const room=state.room,staff=['staff','research'].includes(room),pool=PEER_LINES[room];if(!pool)return;
 const available=pool.map((pair,i)=>({pair,key:'ambient:'+room+':'+i})).filter(v=>!state.ambientSeen[v.key]);if(!available.length)return;
 const present=staff?M.NPCS.filter(n=>['colleague','specialist'].includes(n.id)):M.remainingStudents(state);
 const visible=present.filter(p=>!scene.actors||scene.actors.get(p.id)?.group.visible);if(visible.length<2)return;
 const first=Math.floor(Math.random()*visible.length),a=visible[first],others=visible.filter(p=>p.id!==a.id),b=others[Math.floor(Math.random()*others.length)];
 const {pair,key}=available[Math.floor(Math.random()*available.length)];state.ambientSeen[key]=true;scene.facePair?.(a.id,b.id);scene.speak(a.id,pair[0],a.name);
 setTimeout(()=>{if(running&&!$('#modal').open&&!document.hidden&&state.room===room&&(!scene.actors||scene.actors.get(b.id)?.group.visible))scene?.speak(b.id,pair[1],b.name);},1400);
 const relationKey=[a.id,b.id].sort().join(':'),dayKey=M.markKey(state,'peer-'+relationKey);
 if(!state.flags[dayKey]){state.flags[dayKey]=true;if(staff){const relations=state.npcPeerRelations??={};relations[relationKey]=M.clamp((relations[relationKey]||50)+1);((state.npcMemories??={})[a.id]??=[]).unshift({date:M.stamp(state),text:b.name+' 교사와 '+M.ROOMS[room].name+'에서 수업과 학급 업무를 협의했다.'});}else{a.peerRelations[b.id]=M.clamp((a.peerRelations[b.id]||50)+1);b.peerRelations[a.id]=M.clamp((b.peerRelations[a.id]||50)+1);}}
 save();
}
setInterval(()=>{if(!running||$('#modal').open||document.hidden||state.ended||state.academic.phase==='preparation'||state.staffWork?.away)return;if(M.movementBusy(state)||outingPending()){renderJourney();return;}const before=M.unreadCount(state);M.advance(state,speed);render();scene?.sync();if(M.unreadCount(state)>before)sound('message');if(state.minute>=1000)daySummary();else if(Date.now()-lastAmbient>14000){lastAmbient=Date.now();ambient();}if(settings.music)audio.ambience(true);if(state.minute%10<speed)save();},1000);
window.addEventListener('pagehide',()=>{captureCurriculum();pcActive?flushPC():save();});document.addEventListener('visibilitychange',()=>{audio.visibility(document.hidden);if(document.hidden){captureCurriculum();if(pcActive)flushPC();else save();if(scene)scene.keys={};}});
function wireJoystick(){const joy=$('#joystick'),nub=joy.querySelector('span');let active=false;const reset=()=>{active=false;nub.style.transform='';if(scene)scene.joy={x:0,y:0};};joy.addEventListener('pointerdown',e=>{active=true;joy.setPointerCapture(e.pointerId);e.preventDefault();});joy.addEventListener('pointermove',e=>{if(!active)return;const r=joy.getBoundingClientRect();let x=e.clientX-r.left-r.width/2,y=e.clientY-r.top-r.height/2;const len=Math.hypot(x,y);if(len>22){x=x/len*22;y=y/len*22;}nub.style.transform=`translate(${x}px,${y}px)`;if(scene)scene.joy={x:x/22,y:y/22};});joy.addEventListener('pointerup',reset);joy.addEventListener('pointercancel',reset);joy.addEventListener('lostpointercapture',reset);}
render();applySettings();wireJoystick();
try{scene=new ClassroomScene($('#scene'),{getState:()=>state,getPaused:()=>!running||document.hidden,getNameLabels:()=>settings.showNames!==false,onSound:kind=>{if(!document.hidden&&!$('#modal').open)sound(kind);},onZoom:zoomLabel,onJourneyStage,onJourneyProgress:renderJourney,onActivityComplete,onCharacter:id=>id==='teacher'?profile('teacher'):id.startsWith('s')&&id!=='specialist'?talk(id):npcTalk(id),onObject:action=>handle(action),onReady:()=>{$('#scene-loading').classList.add('hidden');zoomLabel(1);},onError:()=>{$('#scene-loading').textContent='이 기기에서 3D 화면을 열지 못했어요. 메뉴에서 수업과 대화는 계속할 수 있습니다.';}});}catch(e){console.error(e);$('#scene-loading').textContent='3D 교실을 불러오지 못했습니다. 메뉴에서 게임을 계속할 수 있어요.';}
setup();
if(document.modelContext?.registerTool){const life=new AbortController();const registrations=[{name:'read_classroom_state',title:'교실 상태 확인',description:'현재 게임 날짜, 시간, 교실, 수업, 학생 수와 예산을 읽습니다. 상태를 변경하지 않습니다.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute:()=>({date:M.stamp(state),room:M.ROOMS[state.room].name,slot:M.currentSlot(state).name,students:state.students.length,budget:state.budget,trust:M.averageTrust(state)})},{name:'open_classroom_character',title:'인물 기록 열기',description:'학생 또는 교직원의 인물창을 엽니다. 메모나 수치를 변경하지 않습니다.',inputSchema:{type:'object',properties:{characterId:{type:'string'}},required:['characterId'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:input=>{if(!input||typeof input.characterId!=='string'||!state.students.some(s=>s.id===input.characterId)&&!M.NPCS.some(s=>s.id===input.characterId))throw Error('Unknown character');profile(input.characterId);return {opened:input.characterId};}}];for(const tool of registrations){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:life.signal})).catch(()=>{});}catch{}}window.addEventListener('pagehide',()=>life.abort(),{once:true});}

const editable=target=>!!target.closest?.('input,textarea,[contenteditable="true"]');document.addEventListener('selectstart',e=>{if(!editable(e.target))e.preventDefault();});document.addEventListener('dragstart',e=>{if(!editable(e.target))e.preventDefault();});

document.addEventListener('input',e=>{if(e.target.id==='sound-volume'){$('#volume-output').textContent=e.target.value+'%';audio.configure({sound:$('#sound-toggle').checked,volume:e.target.value});}});
